from itertools import combinations as comb

def check_skew(pairs):
    m = len(pairs)
    for i in range(m):
        A_i, B_i = pairs[i]
        if A_i & B_i: return False
    for i in range(m):
        for j in range(i+1, m):
            if not (pairs[i][0] & pairs[j][1]): return False
    return True

# a=2, b=1, bound = C(3,2) = 3
ground = list(range(1,7))
possible_As = [frozenset(s) for k in range(3) for s in comb(ground, k)]
possible_Bs = [frozenset(s) for k in range(2) for s in comb(ground, k)]
pool = [(A,B) for A in possible_As for B in possible_Bs if not (A & B)]

max_found = 0
for r in range(1, min(len(pool)+1, 8)):
    found = False
    for subset in comb(pool, r):
        if check_skew(subset):
            if r > max_found:
                max_found = r
                best_example = subset
            found = True
            break
    if not found:
        break
print(f'a=2,b=1: max m found = {max_found}, bound = {3}')
if max_found > 0:
    print(f'example: {[(set(A),set(B)) for A,B in best_example]}')
